import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { adminApi } from '../api/admin';
import { AdminOrderRow, Pagination } from '../types';
import { useShop } from '../context/ShopContext';
import { useAuth } from '../context/AuthContext';
import {
  ShoppingBag,
  Search,
  Filter,
  Calendar,
  ArrowRight,
  Loader2,
  RefreshCw,
  AlertCircle,
  EyeOff,
  Truck,
  CheckCircle2,
  XCircle,
  Clock,
} from 'lucide-react';

export const AdminOrders: React.FC = () => {
  const { formatPrice } = useShop();
  const { user, hasRole } = useAuth();
  const isFinance = hasRole(['admin', 'super_admin', 'finance']);

  const [orders, setOrders] = useState<AdminOrderRow[]>([]);
  const [pagination, setPagination] = useState<Pagination>({
    page: 1,
    limit: 25,
    total: 0,
    totalPages: 1,
  });
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Filters
  const [statusFilter, setStatusFilter] = useState('');
  const [searchFilter, setSearchFilter] = useState('');

  const fetchOrders = async (targetPage = 1) => {
    setLoading(true);
    setError(null);
    try {
      const res = await adminApi.getOrders({
        page: targetPage,
        limit: pagination.limit,
        status: statusFilter || undefined,
        search: searchFilter.trim() || undefined,
      });
      setOrders(res.orders);
      setPagination(res.pagination);
    } catch (err: any) {
      setError(err?.error || err?.message || 'Could not load admin orders.');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchOrders(1);
  }, [statusFilter]);

  const handleSearch = (e: React.FormEvent) => {
    e.preventDefault();
    fetchOrders(1);
  };

  return (
    <div className="max-w-6xl mx-auto px-4 py-12">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-8 pb-6 border-b border-slate-200 dark:border-slate-800">
        <div>
          <div className="flex items-center gap-2">
            <span className="text-[11px] font-mono uppercase tracking-wider text-emerald-600 dark:text-emerald-400 font-bold">
              OPERATIONS QUEUE
            </span>
            <span className="px-2 py-0.5 rounded-full text-[10px] font-semibold bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 border border-emerald-500/20 font-mono">
              {isFinance ? 'Finance Privileged' : 'Support Redacted Mode'}
            </span>
          </div>
          <h1 className="font-display text-2xl sm:text-3xl font-bold text-slate-900 dark:text-white mt-1">
            Orders Management
          </h1>
          <p className="text-xs sm:text-sm text-slate-500 dark:text-slate-400 mt-1">
            Browse, filter, and inspect Store orders, shipping milestones, and cancellations.
          </p>
        </div>

        <button
          type="button"
          onClick={() => fetchOrders(pagination.page)}
          disabled={loading}
          className="self-start sm:self-auto px-3.5 py-2 rounded-xl border border-slate-200 dark:border-slate-800 hover:bg-slate-100 dark:hover:bg-slate-900 text-xs font-semibold text-slate-700 dark:text-slate-300 inline-flex items-center gap-1.5 transition-colors"
        >
          <RefreshCw size={13} className={loading ? 'animate-spin' : ''} />
          <span>Refresh</span>
        </button>
      </div>

      {/* Filter toolbar */}
      <div className="p-4 rounded-2xl bg-white dark:bg-[#101216] border border-slate-200 dark:border-slate-800 shadow-sm mb-6 flex flex-col sm:flex-row items-center gap-3">
        <form onSubmit={handleSearch} className="flex-1 w-full flex items-center gap-2">
          <div className="relative flex-1">
            <Search size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
            <input
              type="text"
              value={searchFilter}
              onChange={e => setSearchFilter(e.target.value)}
              placeholder="Search by order ID, customer ID, or notes..."
              className="w-full pl-9 pr-4 py-2 rounded-xl bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-800 text-xs text-slate-900 dark:text-white focus:outline-none focus:border-emerald-500 font-mono"
            />
          </div>
          <button
            type="submit"
            className="px-4 py-2 rounded-xl bg-slate-900 dark:bg-white text-white dark:text-slate-900 text-xs font-semibold"
          >
            Search
          </button>
        </form>

        <div className="flex items-center gap-2 w-full sm:w-auto">
          <Filter size={14} className="text-slate-400 shrink-0" />
          <select
            value={statusFilter}
            onChange={e => setStatusFilter(e.target.value)}
            className="px-3 py-2 rounded-xl bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-800 text-xs text-slate-900 dark:text-white focus:outline-none font-mono"
          >
            <option value="">All Statuses</option>
            <option value="CREATED">CREATED</option>
            <option value="PENDING_PAYMENT">PENDING_PAYMENT</option>
            <option value="PAID">PAID</option>
            <option value="PROCESSING">PROCESSING</option>
            <option value="SHIPPED">SHIPPED</option>
            <option value="DELIVERED">DELIVERED</option>
            <option value="PARTIALLY_REFUNDED">PARTIALLY_REFUNDED</option>
            <option value="REFUNDED">REFUNDED</option>
            <option value="CANCELLED">CANCELLED</option>
            <option value="FAILED">FAILED</option>
          </select>
        </div>
      </div>

      {loading ? (
        <div className="flex flex-col items-center justify-center py-20 text-slate-400">
          <Loader2 size={32} className="animate-spin text-emerald-500 mb-3" />
          <span className="text-xs font-mono">Loading operations queue...</span>
        </div>
      ) : error ? (
        <div className="p-8 rounded-2xl bg-rose-500/10 border border-rose-500/20 text-center max-w-md mx-auto">
          <AlertCircle size={28} className="text-rose-500 mx-auto mb-3" />
          <h2 className="font-display text-base font-bold text-slate-900 dark:text-white mb-1">
            Could Not Load Orders
          </h2>
          <p className="text-xs text-slate-500 dark:text-slate-400 mb-4">{error}</p>
          <button
            type="button"
            onClick={() => fetchOrders(1)}
            className="px-4 py-2 bg-emerald-600 text-white rounded-lg text-xs font-semibold"
          >
            Retry
          </button>
        </div>
      ) : orders.length === 0 ? (
        <div className="p-12 rounded-2xl bg-white dark:bg-[#101216] border border-slate-200 dark:border-slate-800 text-center max-w-md mx-auto">
          <ShoppingBag size={28} className="text-slate-400 mx-auto mb-3" />
          <h2 className="font-display text-lg font-bold text-slate-900 dark:text-white mb-1">
            No Orders Match Filters
          </h2>
          <p className="text-xs text-slate-500 dark:text-slate-400">
            No orders found matching the specified status and search criteria.
          </p>
        </div>
      ) : (
        <div className="space-y-3">
          {orders.map(order => (
            <div
              key={order.orderId}
              className="p-5 rounded-2xl bg-white dark:bg-[#101216] border border-slate-200 dark:border-slate-800 shadow-sm flex flex-col md:flex-row md:items-center justify-between gap-4"
            >
              <div className="space-y-1.5">
                <div className="flex flex-wrap items-center gap-2.5">
                  <span className="font-mono text-xs font-bold text-slate-900 dark:text-white">
                    #{order.orderId}
                  </span>
                  <span className="px-2 py-0.5 rounded text-[10px] font-mono font-bold bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-300">
                    {order.status}
                  </span>
                  {order.fulfillmentStatus && (
                    <span className="text-[10px] font-mono text-slate-500 dark:text-slate-400">
                      Fulfillment: {order.fulfillmentStatus}
                    </span>
                  )}
                </div>

                <div className="text-xs text-slate-500 dark:text-slate-400 font-mono flex flex-wrap items-center gap-4">
                  <span className="flex items-center gap-1">
                    <Calendar size={12} />
                    <span>{new Date(order.createdAt).toLocaleDateString()}</span>
                  </span>
                  <span>Customer: {order.userId}</span>
                  <span>Items: {order.itemCount}</span>
                </div>
              </div>

              <div className="flex items-center justify-between md:justify-end gap-6 pt-3 md:pt-0 border-t md:border-t-0 border-slate-100 dark:border-slate-800">
                <div className="text-left md:text-right">
                  <div className="text-[10px] uppercase font-mono tracking-wider text-slate-400">
                    Order Total
                  </div>
                  {order.totalAmount !== undefined ? (
                    <div className="font-mono text-sm font-bold text-emerald-600 dark:text-emerald-400">
                      {formatPrice(order.totalAmount, order.currency)}
                    </div>
                  ) : (
                    <div className="flex items-center gap-1 text-slate-400 text-xs font-mono" title="Redacted by server for non-finance staff">
                      <EyeOff size={12} />
                      <span>[Redacted]</span>
                    </div>
                  )}
                </div>

                <Link
                  to={`/admin/orders/${order.orderId}`}
                  className="px-4 py-2 rounded-xl bg-slate-100 hover:bg-slate-200 dark:bg-slate-800 dark:hover:bg-slate-700 text-xs font-semibold text-slate-900 dark:text-white inline-flex items-center gap-1.5 transition-colors"
                >
                  <span>Manage</span>
                  <ArrowRight size={13} />
                </Link>
              </div>
            </div>
          ))}

          {pagination.totalPages > 1 && (
            <div className="flex items-center justify-center gap-2 pt-6">
              <button
                type="button"
                disabled={pagination.page <= 1}
                onClick={() => fetchOrders(pagination.page - 1)}
                className="px-3 py-1.5 rounded-lg border border-slate-200 dark:border-slate-800 text-xs font-semibold disabled:opacity-30"
              >
                Previous
              </button>
              <span className="text-xs font-mono text-slate-500 px-3">
                Page {pagination.page} of {pagination.totalPages}
              </span>
              <button
                type="button"
                disabled={pagination.page >= pagination.totalPages}
                onClick={() => fetchOrders(pagination.page + 1)}
                className="px-3 py-1.5 rounded-lg border border-slate-200 dark:border-slate-800 text-xs font-semibold disabled:opacity-30"
              >
                Next
              </button>
            </div>
          )}
        </div>
      )}
    </div>
  );
};

export default AdminOrders;
